head.script:
scwin.vIsurCd = '', scwin.vMktactCd = '';
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.arrPar = new Array();
scwin.processGp; // 등록 1, 수정 2

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        scwin.fn_GetPar(scwin.arrPar);
        scwin.vIsurCd = scwin.arrPar[0].ISUR_CD;
        if (scwin.arrPar[0].MKTACT_TP_CD !== undefined) {
            scwin.vMktactCd = scwin.arrPar[0].MKTACT_TP_CD;
        }
    }
};

/**
 * @method
 * @name list
 * @description 채권기준명 리스트를 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function() {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_ISU_BAS_NM";
    url += "&queryId=lds.stf.bnscommon.select.listIsuBasNm";
    url += "&SCREN_ID=" + 'ULDBNS20801.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_ISUR_CD=" + scwin.vIsurCd;
    url += "&{P}V_POP_YN=" + 'Y';
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name inputCheck
 * @description 필수 입력값 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.inputCheck = async function() {
    if (txb_BasIsuNm.getValue() === '') {
        await $c.win.alert("[한글기준명]을 입력하십시오.");
        txb_BasIsuNm.focus();
        return false;
    }
    if (txb_BasIsuAbbrv.getValue() === '') {
        await $c.win.alert("[한글기준약명]을 입력하십시오.");
        txb_BasIsuAbbrv.focus();
        return false;
    }
    if (txb_BasIsuEngNm.getValue() === '') {
        await $c.win.alert("[영문기준명]을 입력하십시오.");
        txb_BasIsuEngNm.focus();
        return false;
    }
    if (txb_BasIsuEngAbbrv.getValue() === '') {
        await $c.win.alert("[영문기준약명]을 입력하십시오.");
        txb_BasIsuEngAbbrv.focus();
        return false;
    }

    // 자리수 체크
    if (!$c.stf.checkMaxLength(txb_BasIsuNm, 60, '한글기준명')) return false;
    if (!$c.stf.checkMaxLength(txb_BasIsuAbbrv, 20, '한글기준약명')) return false;
    if (!$c.stf.checkMaxLength(txb_BasIsuEngNm, 60, '영문기준명')) return false;
    if (!$c.stf.checkMaxLength(txb_BasIsuEngAbbrv, 20, '영문기준약명')) return false;
    const pattern = /^[ㄱ-ㅎ|ㅏ-ㅣ|가-힣]/;
    let str = txb_BasIsuEngNm.getValue();
    for (let i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            await $c.win.alert('영문기준명에 한글은 사용할 수 없습니다');
            txb_BasIsuEngNm.focus();
            return false;
        }
    }
    let str = txb_BasIsuEngAbbrv.getValue();
    for (let i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            await $c.win.alert('영문기준약명에 한글은 사용할 수 없습니다');
            txb_BasIsuEngAbbrv.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name duplCheck
 * @description 등록 시, 중복 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.duplCheck = async function() {
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        if (txb_BasIsuNm.getValue() === dts_List.getCellData(i, "BAS_ISU_NM")) {
            await $c.win.alert("동일한 [한글기준명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuNm.focus();
            return false;
        }
        if (txb_BasIsuAbbrv.getValue() === dts_List.getCellData(i, "BAS_ISU_ABBRV")) {
            await $c.win.alert("동일한 [한글기준약명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuAbbrv.focus();
            return false;
        }
        if (txb_BasIsuEngNm.getValue() === dts_List.getCellData(i, "BAS_ISU_ENG_NM")) {
            await $c.win.alert("동일한 [영문기준명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuEngNm.focus();
            return false;
        }
        if (txb_BasIsuEngAbbrv.getValue() === dts_List.getCellData(i, "BAS_ISU_ENG_ABBRV")) {
            await $c.win.alert("동일한 [영문기준약명]이 존재합니다. 다시 입력하십시오.");
            txb_BasIsuEngAbbrv.focus();
            return false;
        }
    }
};

/**
 * @method
 * @name insertMod
 * @description 등록 및 수정을 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insertMod = async function() {
    // 필수입력값 체크
    if (await scwin.inputCheck() === false) return;
    const vBfBasIsuNm = dts_List.getCellData(dts_List.getRowPosition(), "BAS_ISU_NM");
    let url;
    if (scwin.processGp === '1') {
        // 중복체크
        if (await scwin.duplCheck() === false) return;
        if (!confirm("기준명 " + txb_BasIsuNm.getValue() + "(으)로 등록하시겠습니까?")) return;
        url = "/bns/ListBzAppl.do?method=createIsuBas";
    }
    url += "&SCREN_ID=" + 'ULDBNS20801.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&ISUR_CD=" + scwin.vIsurCd;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_IsuInfo)";
    trs_Save.Post();
};

/**
 * @method
 * @name getStkIsuNm
 * @description 주권종목명 팝업에 넘길 키데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getStkIsuNm = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: scwin.vIsurCd,
        POP_CALL_YN: 'Y'
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name getModIsuNm
 * @description 수정 팝업(종목기준명관리)에 넘길 키데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getModIsuNm = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: scwin.vIsurCd,
        BAS_ISU_NM: txb_BasIsuNm.getValue(),
        BAS_ISU_ABBRV: txb_BasIsuAbbrv.getValue(),
        BAS_ISU_ENG_NM: txb_BasIsuEngNm.getValue(),
        BAS_ISU_ENG_ABBRV: txb_BasIsuEngAbbrv.getValue(),
        ISUR_NM: dts_List.getCellData(dts_List.getRowPosition(), "ISUR_NM"),
        POP_CALL: "Y"
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name setModIsuNm
 * @description 수정 팝업(종목기준명관리)에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setModIsuNm = async function(arrPar) {
    if ("Y" === scwin.arrPar[0].MOD_YN) {
        await $c.win.alert("수정 처리 성공했습니다.");
        dts_List.Reset();
    }
    if ("Y" === scwin.arrPar[0].DEL_YN) {
        dts_List.Reset();
        scwin.clearTextField();
    }
};

/**
 * @method
 * @name popAdminIsurNm
 * @description 채권기준명관리 팝업을 보여준다.
 * @param {*} grdObj grdObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popAdminIsurNm = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
    const options = {
        id: "ULDBNS20800",
        title: "채권기준명 관리",
        type: "browserPopup",
        width: "1260px",
        height: "785px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/bnslistbzappl/ULDBNS20800.gfm", options);
};

/**
 * @method
 * @name clearTextField
 * @description 텍스트 필드를 초기화 한다.
 * @returns {void}
 * @hidden N
 */
scwin.clearTextField = function() {
    dts_List.setRowPosition(0, 0);
    txb_BasIsuNm.setValue('');
    txb_BasIsuAbbrv.setValue('');
    txb_BasIsuEngNm.setValue('');
    txb_BasIsuEngAbbrv.setValue('');
};

/***************************************************************************************
 * 201,202에서 호출하여 수정 처리 후
 * 화면을 닫을 경우,  콤보박스 리셋 용도 (닫기 버튼이 아닌 X버튼 및 Alt+F4 종료시도 리셋 되어야 하므로)
 ***************************************************************************************/
window.onunload = function() {
    if (scwin.vMktactCd !== '' && scwin.processGp === '2') {
        // 부모 창 전송 값 설정
        scwin.arrPar[0].SUCCESS_YN = 'Y';
        opener.scwin.fn_SetPar(scwin.arrPar);
    }
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_info);
    // 호출파라미터설정
    scwin.setParam();
    // 목록조회
    await scwin.list();
    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_IsuInfo",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_IsuInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    lbl_Pop.hide(); // 팝업위치 레이블 숨김

};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotalCnt.setValue("총 " + rowcount + "건");
    dts_List.setRowPosition(0, 0);
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    scwin.arrPar[0] = {
        BAS_ISU_NM: dts_List.getCellData(row, "BAS_ISU_NM"),
        BAS_ISU_ABBRV: dts_List.getCellData(row, "BAS_ISU_ABBRV"),
        BAS_ISU_ENG_NM: dts_List.getCellData(row, "BAS_ISU_ENG_NM"),
        BAS_ISU_ENG_ABBRV: dts_List.getCellData(row, "BAS_ISU_ENG_ABBRV")
    };
    scwin.fn_SetPar(scwin.arrPar);
    await $c.win.closePopup();
};

/**
 * @method
 * @name dts_IsuInfo_OnLoadError
 * @description dts_IsuInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_IsuInfo_OnLoadError = async function() {
    await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};

/**
 * @method
 * @name dts_IsuInfo_OnLoadCompleted
 * @description dts_IsuInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_IsuInfo_OnLoadCompleted = function(rowcount) {
    dts_IsuInfo.insertRow();
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnClick = function(row, colid) {
    dts_IsuInfo.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    dts_IsuInfo.setCellData(1, "BAS_ISU_NM", dts_List.getCellData(row, "BAS_ISU_NM"));
    dts_IsuInfo.setCellData(1, "BAS_ISU_ABBRV", dts_List.getCellData(row, "BAS_ISU_ABBRV"));
    dts_IsuInfo.setCellData(1, "BAS_ISU_ENG_NM", dts_List.getCellData(row, "BAS_ISU_ENG_NM"));
    dts_IsuInfo.setCellData(1, "BAS_ISU_ENG_ABBRV", dts_List.getCellData(row, "BAS_ISU_ENG_ABBRV"));
};

/**
 * @method
 * @name btn_Reset_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Reset_onclick = function() {
    scwin.clearTextField();
};

/**
 * @method
 * @name btn_Cfm_onclick
 * @description 「주권종목명확인」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Cfm_onclick = function() {
    scwin.fn_GetPar = scwin.getStkIsuNm;
    $c.bns.fn_PopStkIsuSearch(lbl_Pop);
};

/**
 * @method
 * @name btn_Insert_onclick
 * @description 「채권기준명등록」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Insert_onclick = async function() {
    scwin.processGp = '1';
    dts_IsuInfo.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    await scwin.insertMod();
};

/**
 * @method
 * @name btn_Mod_onclick
 * @description 「채권기준명수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Mod_onclick = async function() {
    if (dts_List.getRowCount() === 0) return;
    scwin.processGp = '2';
    scwin.fn_GetPar = scwin.getModIsuNm;
    scwin.fn_SetPar = scwin.setModIsuNm;
    await scwin.popAdminIsurNm(lbl_Pop);
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    if (scwin.processGp === '1') {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
    }
    dts_List.Reset();

    // 201, 202만 호출 시 넘김 (콤보박스 리셋 용도, 닫기 버튼이 아닌 X버튼 및 Alt+F4 종료시도 리셋 되어야 하므로)
    if (scwin.vMktactCd !== '') {
        // 부모 창 전송 값 설정
        scwin.arrPar[0].SUCCESS_YN = 'Y';
        scwin.fn_SetPar(scwin.arrPar);
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    if (scwin.processGp === '1') {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "등록"));
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};
